import { isUndefined } from 'lodash-es';
import React, { Fragment, useRef } from 'react';
import styled from 'styled-components';

import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { AnnotationsTooltipItem } from './AnnotationsTooltipItem.js';
import { ESTIMATED_ACTION_HEIGHT } from './constants-virtualization-list.js';
import { Flex } from '../../../../../../layouts-core/flex/Flex.js';
import { Divider } from '../../../../../../typography/Divider.js';
import { TooltipItem } from '../../../../types/tooltip.js';
import { ChartActionsMenu } from '../../../series-action/ChartActionsMenu.js';
import { mergeTooltipActions } from '../../../series-action/functions/mergeTooltipActions.js';
import { useChartActionsMenu } from '../../../series-action/hooks/useChartActionsMenu.js';
import { InteractiveChartTooltip } from '../../../tooltip/InteractiveChartTooltip/components/InteractiveChartTooltip.js';
import { TimebasedTooltipHeader } from '../../../tooltip/InteractiveChartTooltip/headers/TimebasedTooltipHeader.js';
import { TooltipActionTemplate } from '../../../tooltip/shared/hooks/useTooltipSeriesActions.js';
import { sumAnnotationsHeights } from '../../functions/sum-annotations-heights.js';
import {
  useAnnotationsTooltipState,
  useAnnotationsSelectionState,
} from '../../hooks/store/selectors.js';
import {
  useSetStateTooltip,
  useSetStateSelection,
} from '../../hooks/store/state-setters.js';
import { useAnnotationsActions } from '../../hooks/useAnnotationsActions.js';
import { useMarkersInteractions } from '../../hooks/useMarkersInteractions.js';
import { useRegisterTooltipHandlerCallbacks } from '../../hooks/useRegisterTooltipHandlerCallbacks.js';
import { initialState } from '../../providers/AnnotationsDataInitialState.js';
import { AnnotationData } from '../../types/annotations.js';

const StyledTooltipItemContent = /* @__PURE__ */ styled(Flex)({
  padding: Spacings.Size4,
  flexDirection: 'column',
});

/**
 * Tooltip specific to the annotations chart
 */
export const AnnotationsTooltip = () => {
  const ref = useRef<HTMLDivElement>(null);
  const { actions } = useAnnotationsActions();
  const { pinned, data, visibility, position } = useAnnotationsTooltipState();
  const selection = useAnnotationsSelectionState();
  const updateTooltipState = useSetStateTooltip();
  const updateSelectionState = useSetStateSelection();
  const { onMarkersInteraction } = useMarkersInteractions();

  const {
    selectedItem,
    updateSelectedItem,
    actionsMenuRef,
    onLeave: handleMenuLeave,
  } = useChartActionsMenu();

  const hideTooltip = () => {
    updateTooltipState(initialState.tooltip);
    updateSelectionState(initialState.selection);
    onMarkersInteraction?.(initialState.selection);
  };
  useRegisterTooltipHandlerCallbacks(ref, hideTooltip);

  const showTooltip = !!(data && visibility && position);
  const showCustomActions = actions && !isUndefined(selection.selectedListItem);

  const actionClickHandler = () => {
    updateSelectedItem('');
  };

  const calculateVirtualItemHeight = (index: number): number =>
    showCustomActions
      ? ESTIMATED_ACTION_HEIGHT
      : sumAnnotationsHeights(index, data ?? []);

  const handleMouseLeave = (event: React.MouseEvent) => {
    const { hoveredListItem, hoverGroupListKey } = initialState.selection;

    const newSelection = {
      hoveredListItem,
      hoverGroupListKey,
    };

    updateSelectionState(newSelection);
    onMarkersInteraction?.(newSelection);
    handleMenuLeave(event);
  };

  const getTooltipItem = (annotation: AnnotationData) => {
    return {
      ...annotation,
      name: annotation.title,
      values: [annotation.title, annotation.description],
    } as TooltipItem;
  };

  const seriesActionsCallback = (annotation: AnnotationData) =>
    mergeTooltipActions(
      getTooltipItem(annotation),
      actions as unknown as TooltipActionTemplate,
    );

  return showTooltip ? (
    <InteractiveChartTooltip
      position={position}
      pinned={pinned}
      itemSize={calculateVirtualItemHeight}
      ref={ref}
      onMouseLeave={handleMouseLeave}
    >
      <InteractiveChartTooltip.Body>
        {data?.map((annotationGroup, index) => (
          <Fragment key={annotationGroup.key}>
            <TimebasedTooltipHeader
              timeframe={[annotationGroup.start, annotationGroup.end]}
            />
            <StyledTooltipItemContent>
              {annotationGroup.annotations.map((annotation, index) => {
                return (
                  <ChartActionsMenu
                    key={index}
                    isOpen={selectedItem === annotation.id}
                    actions={() => seriesActionsCallback(annotation)()}
                    ref={actionsMenuRef}
                    onActionClick={actionClickHandler}
                  >
                    <AnnotationsTooltipItem
                      annotation={annotation}
                      onMouseOver={() => updateSelectedItem(annotation.id)}
                    />
                  </ChartActionsMenu>
                );
              })}
            </StyledTooltipItemContent>
            {index !== data.length - 1 && <Divider />}
          </Fragment>
        ))}
      </InteractiveChartTooltip.Body>
    </InteractiveChartTooltip>
  ) : null;
};
AnnotationsTooltip['displayName'] = 'AnnotationChartTooltip';
